import{_ as s,o as e,c as n,a2 as p}from"./chunks/framework.DYYBR_aZ.js";const u=JSON.parse('{"title":"Spring Data Redis 常用操作：从 Java API 到 Redis 命令","description":"","frontmatter":{},"headers":[],"relativePath":"java/Spring Data Redis 常用操作：从 Java API 到 Redis 命令.md","filePath":"java/Spring Data Redis 常用操作：从 Java API 到 Redis 命令.md"}'),t={name:"java/Spring Data Redis 常用操作：从 Java API 到 Redis 命令.md"};function i(o,a,l,d,c,r){return e(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="spring-data-redis-常用操作-从-java-api-到-redis-命令" tabindex="-1">Spring Data Redis 常用操作：从 Java API 到 Redis 命令 <a class="header-anchor" href="#spring-data-redis-常用操作-从-java-api-到-redis-命令" aria-label="Permalink to &quot;Spring Data Redis 常用操作：从 Java API 到 Redis 命令&quot;">​</a></h1><h2 id="一、为什么需要学习-spring-data-redis" tabindex="-1">一、为什么需要学习 Spring Data Redis？ <a class="header-anchor" href="#一、为什么需要学习-spring-data-redis" aria-label="Permalink to &quot;一、为什么需要学习 Spring Data Redis？&quot;">​</a></h2><p>在 Java 后端开发中，我们通常不会直接通过命令行操作 Redis，而是使用 Spring Data Redis 提供的 Java API 完成数据读写。</p><p>例如，在 oneCoupon 优惠券项目中，查询优惠券模板时使用了下面的代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Map&lt;Object, Object&gt; couponTemplateCacheMap =</span></span>
<span class="line"><span>        stringRedisTemplate.opsForHash()</span></span>
<span class="line"><span>                .entries(couponTemplateCacheKey);</span></span></code></pre></div><p>如果你已经了解 Redis，就知道这段代码是在读取 Hash 数据；但如果还不熟悉 Spring Data Redis，就可能不知道 <code>stringRedisTemplate</code>、<code>opsForHash()</code> 和 <code>entries()</code> 分别是什么，以及它们最终对应什么 Redis 命令。</p><p>因此，学习 Redis 的 Java 操作时，建议同时理解三个层次：</p><ol><li><strong>Java API：</strong> 业务代码通过什么方法操作 Redis？</li><li><strong>Redis 数据结构与命令：</strong> 数据存储在哪里，底层执行什么操作？</li><li><strong>业务用途：</strong> 为什么要这样操作，解决了什么问题？</li></ol><p>掌握这三个层次之后，再阅读缓存、分布式锁和高并发业务代码，就会容易得多。</p><h2 id="二、redistemplate-与-stringredistemplate" tabindex="-1">二、RedisTemplate 与 StringRedisTemplate <a class="header-anchor" href="#二、redistemplate-与-stringredistemplate" aria-label="Permalink to &quot;二、RedisTemplate 与 StringRedisTemplate&quot;">​</a></h2><p>Spring Data Redis 提供了 <code>RedisTemplate</code> 和 <code>StringRedisTemplate</code> 等工具类，帮助 Java 程序访问 Redis。</p><h3 id="_1-redistemplate" tabindex="-1">1. RedisTemplate <a class="header-anchor" href="#_1-redistemplate" aria-label="Permalink to &quot;1. RedisTemplate&quot;">​</a></h3><p><code>RedisTemplate</code> 是一个通用的 Redis 操作模板，可以通过配置不同的序列化器，处理不同类型的 Key 和 Value。</p><p>Java 对象不能直接以任意形式存入 Redis。通常需要先进行序列化，将对象转换为适合存储和传输的数据表示；读取时再进行反序列化。</p><p>因此，使用 <code>RedisTemplate</code> 时，需要注意 Key、Value 以及 Hash 字段和值分别采用什么序列化方式。</p><h3 id="_2-stringredistemplate" tabindex="-1">2. StringRedisTemplate <a class="header-anchor" href="#_2-stringredistemplate" aria-label="Permalink to &quot;2. StringRedisTemplate&quot;">​</a></h3><p><code>StringRedisTemplate</code> 是 <code>RedisTemplate</code> 的常用特化实现，默认采用字符串序列化方式，适合操作以字符串表示的 Key、Value 和 Hash 字段。</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stringRedisTemplate.opsForValue()</span></span>
<span class="line"><span>        .set(&quot;username&quot;, &quot;zhangsan&quot;);</span></span></code></pre></div><p>从业务角度看，这段代码是在 Redis 中保存一个字符串；从 Redis 数据结构的角度看，它使用的是 String 类型。</p><h3 id="_3-为什么需要-opsforxxx" tabindex="-1">3. 为什么需要 opsForXxx()？ <a class="header-anchor" href="#_3-为什么需要-opsforxxx" aria-label="Permalink to &quot;3. 为什么需要 opsForXxx()？&quot;">​</a></h3><p><code>StringRedisTemplate</code> 提供了多个操作入口，用于访问不同的 Redis 数据结构。</p><table tabindex="0"><thead><tr><th>Java API</th><th>对应的数据结构</th><th>典型用途</th></tr></thead><tbody><tr><td><code>opsForValue()</code></td><td>String</td><td>缓存字符串、计数值</td></tr><tr><td><code>opsForHash()</code></td><td>Hash</td><td>存储对象的多个字段</td></tr><tr><td><code>opsForList()</code></td><td>List</td><td>列表、队列相关操作</td></tr><tr><td><code>opsForSet()</code></td><td>Set</td><td>去重、集合运算</td></tr><tr><td><code>opsForZSet()</code></td><td>ZSET</td><td>排行榜、按分数排序</td></tr></tbody></table><p>需要注意，<code>opsForXxx()</code> 是 Spring Data Redis 的 Java API，并不是 Redis 原生命令。它们为不同的数据结构提供了更方便的操作入口。</p><h2 id="三、常用-redis-操作及其对应命令" tabindex="-1">三、常用 Redis 操作及其对应命令 <a class="header-anchor" href="#三、常用-redis-操作及其对应命令" aria-label="Permalink to &quot;三、常用 Redis 操作及其对应命令&quot;">​</a></h2><p>下面结合常见 Java 后端开发场景，介绍最常用的 Redis 操作。</p><h3 id="_1-string-保存和读取简单数据" tabindex="-1">1. String：保存和读取简单数据 <a class="header-anchor" href="#_1-string-保存和读取简单数据" aria-label="Permalink to &quot;1. String：保存和读取简单数据&quot;">​</a></h3><p>String 是 Redis 最常用的数据类型之一，可以保存字符串、数字等内容。</p><p><strong>写入数据：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stringRedisTemplate.opsForValue()</span></span>
<span class="line"><span>        .set(&quot;username&quot;, &quot;zhangsan&quot;);</span></span></code></pre></div><p>对应的 Redis 命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET username zhangsan</span></span></code></pre></div><p><strong>读取数据：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>String username =</span></span>
<span class="line"><span>        stringRedisTemplate.opsForValue()</span></span>
<span class="line"><span>                .get(&quot;username&quot;);</span></span></code></pre></div><p>对应的 Redis 命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET username</span></span></code></pre></div><p><strong>设置过期时间：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stringRedisTemplate.opsForValue()</span></span>
<span class="line"><span>        .set(&quot;verification_code&quot;, &quot;123456&quot;,</span></span>
<span class="line"><span>                5, TimeUnit.MINUTES);</span></span></code></pre></div><p>这表示保存验证码，并设置五分钟的有效期。概念上对应：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET verification_code 123456 EX 300</span></span></code></pre></div><p><code>EX 300</code> 表示过期时间为 300 秒。使用带过期时间的 <code>set()</code>，可以在设置值的同时指定有效期，避免先写入、再单独设置过期时间所带来的中间状态问题。</p><h3 id="_2-hash-保存对象的多个字段" tabindex="-1">2. Hash：保存对象的多个字段 <a class="header-anchor" href="#_2-hash-保存对象的多个字段" aria-label="Permalink to &quot;2. Hash：保存对象的多个字段&quot;">​</a></h3><p>Hash 适合保存一个对象的多个字段，例如优惠券模板的名称、状态和优惠金额。</p><p><strong>写入一个字段：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stringRedisTemplate.opsForHash()</span></span>
<span class="line"><span>        .put(&quot;coupon:1001&quot;, &quot;name&quot;, &quot;新人优惠券&quot;);</span></span></code></pre></div><p>对应命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HSET coupon:1001 name &quot;新人优惠券&quot;</span></span></code></pre></div><p><strong>读取一个字段：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Object name =</span></span>
<span class="line"><span>        stringRedisTemplate.opsForHash()</span></span>
<span class="line"><span>                .get(&quot;coupon:1001&quot;, &quot;name&quot;);</span></span></code></pre></div><p>对应命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HGET coupon:1001 name</span></span></code></pre></div><p><strong>读取全部字段：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Map&lt;Object, Object&gt; coupon =</span></span>
<span class="line"><span>        stringRedisTemplate.opsForHash()</span></span>
<span class="line"><span>                .entries(&quot;coupon:1001&quot;);</span></span></code></pre></div><p>对应命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HGETALL coupon:1001</span></span></code></pre></div><p>如果 Redis 中保存了多个字段，<code>entries()</code> 会将它们读取为一个 Map。</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HSET coupon:1001 name &quot;新人优惠券&quot; status &quot;ACTIVE&quot;</span></span></code></pre></div><p>读取后，Java 得到的 Map 中包含 <code>name</code> 和 <code>status</code> 两个字段。</p><p><strong>一次写入多个字段：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Map&lt;String, String&gt; fields = new HashMap&lt;&gt;();</span></span>
<span class="line"><span>fields.put(&quot;name&quot;, &quot;新人优惠券&quot;);</span></span>
<span class="line"><span>fields.put(&quot;status&quot;, &quot;ACTIVE&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>stringRedisTemplate.opsForHash()</span></span>
<span class="line"><span>        .putAll(&quot;coupon:1001&quot;, fields);</span></span></code></pre></div><p>这类操作通常通过 <code>HSET</code> 的多字段形式完成。与逐个字段调用 <code>put()</code> 相比，<code>putAll()</code> 可以减少应用与 Redis 之间的请求次数。</p><h3 id="_3-key-判断存在、设置过期时间和删除" tabindex="-1">3. Key：判断存在、设置过期时间和删除 <a class="header-anchor" href="#_3-key-判断存在、设置过期时间和删除" aria-label="Permalink to &quot;3. Key：判断存在、设置过期时间和删除&quot;">​</a></h3><p>Redis 中的数据通常通过 Key 定位，因此检查 Key 是否存在、设置过期时间和删除 Key 都是常见操作。</p><p><strong>判断 Key 是否存在：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Boolean exists =</span></span>
<span class="line"><span>        stringRedisTemplate.hasKey(&quot;coupon:1001&quot;);</span></span></code></pre></div><p>对应命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EXISTS coupon:1001</span></span></code></pre></div><p>如果 Key 存在，Redis 返回存在标记；如果不存在，则返回不存在标记。Java API 使用 <code>Boolean</code>，所以在处理结果时需要考虑它可能为 <code>null</code> 的情况。</p><p><strong>设置过期时间：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stringRedisTemplate.expire(</span></span>
<span class="line"><span>        &quot;coupon:1001&quot;, 30, TimeUnit.MINUTES);</span></span></code></pre></div><p>对应命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EXPIRE coupon:1001 1800</span></span></code></pre></div><p>这里设置的是相对过期时间，即从当前时间起 1800 秒后过期。</p><p><strong>查询剩余过期时间：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Long ttl =</span></span>
<span class="line"><span>        stringRedisTemplate.getExpire(&quot;coupon:1001&quot;);</span></span></code></pre></div><p>对应命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TTL coupon:1001</span></span></code></pre></div><p><code>TTL</code> 可以帮助我们判断 Key 的剩余有效时间。需要注意，返回值可能为负数，例如 <code>-1</code> 表示 Key 存在但没有设置过期时间，<code>-2</code> 表示 Key 不存在。</p><p><strong>删除 Key：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stringRedisTemplate.delete(&quot;coupon:1001&quot;);</span></span></code></pre></div><p>对应命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DEL coupon:1001</span></span></code></pre></div><p>删除 Key 常用于缓存失效、数据清理等场景。</p><h2 id="四、结合-onecoupon-理解正常缓存与空值缓存" tabindex="-1">四、结合 oneCoupon：理解正常缓存与空值缓存 <a class="header-anchor" href="#四、结合-onecoupon-理解正常缓存与空值缓存" aria-label="Permalink to &quot;四、结合 oneCoupon：理解正常缓存与空值缓存&quot;">​</a></h2><p>掌握了基本 API 之后，我们再回到实际项目。</p><p>在 oneCoupon 的优惠券模板查询逻辑中，系统使用两种不同的缓存 Key：一种保存正常的优惠券模板数据，另一种标记某个模板当前不存在或不符合查询条件。</p><h3 id="_1-查询正常缓存" tabindex="-1">1. 查询正常缓存 <a class="header-anchor" href="#_1-查询正常缓存" aria-label="Permalink to &quot;1. 查询正常缓存&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>String couponTemplateCacheKey =</span></span>
<span class="line"><span>        String.format(</span></span>
<span class="line"><span>                EngineRedisConstant.COUPON_TEMPLATE_KEY,</span></span>
<span class="line"><span>                requestParam.getCouponTemplateId()</span></span>
<span class="line"><span>        );</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Map&lt;Object, Object&gt; couponTemplateCacheMap =</span></span>
<span class="line"><span>        stringRedisTemplate.opsForHash()</span></span>
<span class="line"><span>                .entries(couponTemplateCacheKey);</span></span></code></pre></div><p>这里先通过 <code>String.format()</code> 拼接出模板对应的 Key，再调用 <code>opsForHash().entries()</code> 读取 Hash 中的所有字段。</p><p>如果缓存中存在数据，系统就可以将 Map 转换成 <code>CouponTemplateQueryRespDTO</code> 并返回，减少数据库查询。</p><p>如果返回的 Map 为空，则表示没有读取到正常缓存，需要继续判断模板是否可能存在，并决定是否查询数据库。</p><h3 id="_2-检查空值缓存" tabindex="-1">2. 检查空值缓存 <a class="header-anchor" href="#_2-检查空值缓存" aria-label="Permalink to &quot;2. 检查空值缓存&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>String couponTemplateIsNullCacheKey =</span></span>
<span class="line"><span>        String.format(</span></span>
<span class="line"><span>                EngineRedisConstant.COUPON_TEMPLATE_IS_NULL_KEY,</span></span>
<span class="line"><span>                requestParam.getCouponTemplateId()</span></span>
<span class="line"><span>        );</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Boolean hasKeyFlag =</span></span>
<span class="line"><span>        stringRedisTemplate.hasKey(</span></span>
<span class="line"><span>                couponTemplateIsNullCacheKey</span></span>
<span class="line"><span>        );</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if (Boolean.TRUE.equals(hasKeyFlag)) {</span></span>
<span class="line"><span>    throw new ClientException(&quot;优惠券模板不存在&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里使用 <code>hasKey()</code> 判断空值缓存的 Key 是否存在。</p><p>当系统第一次查询某个模板，发现数据库中没有符合条件的记录时，可以写入空值缓存，避免后续相同请求不断查询数据库。</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (couponTemplateDO == null) {</span></span>
<span class="line"><span>    stringRedisTemplate.opsForValue()</span></span>
<span class="line"><span>            .set(couponTemplateIsNullCacheKey,</span></span>
<span class="line"><span>                    &quot;&quot;, 30, TimeUnit.MINUTES);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    throw new ClientException(&quot;优惠券模板不存在或已过期&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>对应的 Redis 操作可以理解为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET one-coupon_engine:template_is_null:1001 &quot;&quot; EX 1800</span></span></code></pre></div><p>这里存储的空字符串只是占位值，真正重要的是 Key 是否存在。</p><p>这种设计称为空值缓存，<strong>主要用于缓解缓存穿透：当某个不存在的模板 ID 被反复请求时，系统可以直接返回，而不必每次都访问 MySQL。</strong></p><p>需要注意，空值缓存有有效期。如果业务允许新建模板或恢复模板，系统还需要考虑空值缓存失效或主动删除的策略，否则可能在缓存有效期内继续返回旧的“不存在”结果。</p><h2 id="五、如何把-java-对象转换成-redis-hash" tabindex="-1">五、如何把 Java 对象转换成 Redis Hash？ <a class="header-anchor" href="#五、如何把-java-对象转换成-redis-hash" aria-label="Permalink to &quot;五、如何把 Java 对象转换成 Redis Hash？&quot;">​</a></h2><p>在 oneCoupon 中，查询数据库得到的 <code>CouponTemplateDO</code> 并不是直接写入 Redis，而是先转换成响应 DTO，再转换为 Map。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CouponTemplateQueryRespDTO actualRespDTO =</span></span>
<span class="line"><span>        BeanUtil.toBean(</span></span>
<span class="line"><span>                couponTemplateDO,</span></span>
<span class="line"><span>                CouponTemplateQueryRespDTO.class</span></span>
<span class="line"><span>        );</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Map&lt;String, Object&gt; cacheTargetMap =</span></span>
<span class="line"><span>        BeanUtil.beanToMap(actualRespDTO, false, true);</span></span></code></pre></div><p>这里涉及两个转换过程：</p><ol><li><code>BeanUtil.toBean()</code>：将数据库实体转换为响应 DTO，避免直接把数据库持久层对象当作缓存接口对象使用。</li><li><code>BeanUtil.beanToMap()</code>：将 DTO 的属性转换为 Map，方便把每个属性作为 Redis Hash 的字段保存。</li></ol><p>随后，项目将 Map 中的字段值转换为字符串：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Map&lt;String, String&gt; actualCacheTargetMap =</span></span>
<span class="line"><span>        cacheTargetMap.entrySet().stream()</span></span>
<span class="line"><span>                .collect(Collectors.toMap(</span></span>
<span class="line"><span>                        Map.Entry::getKey,</span></span>
<span class="line"><span>                        entry -&gt; entry.getValue() != null</span></span>
<span class="line"><span>                                ? entry.getValue().toString()</span></span>
<span class="line"><span>                                : &quot;&quot;</span></span>
<span class="line"><span>                ));</span></span></code></pre></div><p>这样做是因为项目使用 <code>StringRedisTemplate</code>，Hash 的字段和值通常采用字符串序列化方式。</p><p>不过，简单调用 <code>toString()</code> 并不适用于所有对象。对于日期、复杂对象、集合等类型，直接转换可能无法在读取时准确恢复原始类型。如果缓存字段涉及复杂数据，应该明确设计序列化和反序列化规则。</p><h2 id="六、为什么写入-hash-时还要使用-lua" tabindex="-1">六、为什么写入 Hash 时还要使用 Lua？ <a class="header-anchor" href="#六、为什么写入-hash-时还要使用-lua" aria-label="Permalink to &quot;六、为什么写入 Hash 时还要使用 Lua？&quot;">​</a></h2><p>oneCoupon 并没有简单地调用 <code>putAll()</code>，而是通过 Lua 脚本同时写入 Hash 字段和设置过期时间。</p><p>核心脚本如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>String luaScript =</span></span>
<span class="line"><span>        &quot;redis.call(&#39;HMSET&#39;, KEYS[1], unpack(ARGV, 1, #ARGV - 1)) &quot;</span></span>
<span class="line"><span>        + &quot;redis.call(&#39;EXPIREAT&#39;, KEYS[1], ARGV[#ARGV])&quot;;</span></span></code></pre></div><p>理解这段脚本，需要先认识 Redis Lua 脚本中的两个概念：</p><ul><li><code>KEYS</code>：传入脚本的 Redis Key 列表。</li><li><code>ARGV</code>：传入脚本的其他参数列表。</li></ul><p>项目先把 Hash 的字段和值依次放入 <code>args</code>，<strong>最后追加优惠券有效结束时间的 Unix 时间戳</strong>。脚本将最后一个参数作为过期时间，其余参数作为 Hash 字段和值。</p><p>例如，传入的逻辑参数可以表示为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KEYS[1] = coupon:1001</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ARGV = [</span></span>
<span class="line"><span>  &quot;name&quot;, &quot;新人优惠券&quot;,</span></span>
<span class="line"><span>  &quot;status&quot;, &quot;ACTIVE&quot;,</span></span>
<span class="line"><span>  &quot;1790000000&quot;</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>脚本先执行 Hash 写入，再设置绝对过期时间：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HMSET coupon:1001 name &quot;新人优惠券&quot; status &quot;ACTIVE&quot;</span></span>
<span class="line"><span>EXPIREAT coupon:1001 1790000000</span></span></code></pre></div><p>这里的 <code>EXPIREAT</code> 使用 Unix 时间戳，单位是秒。项目通过：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>couponTemplateDO.getValidEndTime().getTime() / 1000</span></span></code></pre></div><p>将 Java 的毫秒时间戳转换为秒。</p><h3 id="为什么要使用-lua" tabindex="-1">为什么要使用 Lua？ <a class="header-anchor" href="#为什么要使用-lua" aria-label="Permalink to &quot;为什么要使用 Lua？&quot;">​</a></h3><p>如果先写入 Hash，再单独设置过期时间，两次操作之间可能有其他客户端命令执行。使用 Lua 脚本可以将这两步作为一个原子执行单元，避免其他客户端命令在脚本执行过程中插入。</p><p><strong>需要注意，Lua 脚本的原子执行不等于数据库事务的回滚能力：如果脚本在第一步完成后，第二步因错误而失败，Redis 不会自动撤销第一步已经完成的写入。</strong></p><p>另外，<code>HMSET</code> 在现代 Redis 中已经被标记为弃用，推荐使用支持多字段参数的 <code>HSET</code>。阅读旧项目时要理解原来的写法；编写新代码时可以优先采用更新的命令。</p><h2 id="七、redis-key-的命名与过期时间" tabindex="-1">七、Redis Key 的命名与过期时间 <a class="header-anchor" href="#七、redis-key-的命名与过期时间" aria-label="Permalink to &quot;七、Redis Key 的命名与过期时间&quot;">​</a></h2><p>在实际项目中，Key 的设计同样重要。</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>one-coupon_engine:template:1001</span></span>
<span class="line"><span>one-coupon_engine:template_is_null:1001</span></span>
<span class="line"><span>one-coupon_engine:lock:template:1001</span></span></code></pre></div><p>通过前缀，可以大致判断 Key 的用途：</p><ul><li><code>template</code>：优惠券模板正常缓存。</li><li><code>template_is_null</code>：空值缓存。</li><li><code>lock:template</code>：缓存重建使用的分布式锁。</li></ul><p>项目还可能通过公共 Key 序列化器增加环境前缀，以避免不同环境的 Key 相互冲突。但要注意，这取决于具体客户端和序列化器配置，并不是所有 Redis 操作都会自动经过同一套 Key 处理逻辑。</p><p>过期时间也需要结合业务含义设计。例如，优惠券模板的正常缓存可以设置为模板有效结束时间，而空值缓存可以设置为固定的 30 分钟。两者的有效期不同，是因为它们保存的数据含义不同。</p><h2 id="八、常见注意事项" tabindex="-1">八、常见注意事项 <a class="header-anchor" href="#八、常见注意事项" aria-label="Permalink to &quot;八、常见注意事项&quot;">​</a></h2><h3 id="_1-redis-数据结构与-java-api-要对应" tabindex="-1">1. Redis 数据结构与 Java API 要对应 <a class="header-anchor" href="#_1-redis-数据结构与-java-api-要对应" aria-label="Permalink to &quot;1. Redis 数据结构与 Java API 要对应&quot;">​</a></h3><p>使用 <code>opsForHash()</code> 就是在操作 Hash；使用 <code>opsForValue()</code> 则是在操作 String。不能因为它们都通过 <code>StringRedisTemplate</code> 调用，就认为它们使用的是相同的数据结构。</p><h3 id="_2-缓存数据的序列化方式要明确" tabindex="-1">2. 缓存数据的序列化方式要明确 <a class="header-anchor" href="#_2-缓存数据的序列化方式要明确" aria-label="Permalink to &quot;2. 缓存数据的序列化方式要明确&quot;">​</a></h3><p>如果将复杂对象直接转换成字符串，后续不一定能恢复原始类型。<strong>对于 DTO、日期、枚举和集合等数据，应明确缓存格式。</strong></p><h3 id="_3-过期时间要与业务有效期相匹配" tabindex="-1">3. 过期时间要与业务有效期相匹配 <a class="header-anchor" href="#_3-过期时间要与业务有效期相匹配" aria-label="Permalink to &quot;3. 过期时间要与业务有效期相匹配&quot;">​</a></h3><p>如果优惠券已经过期，就不应该继续通过正常缓存返回有效模板。使用 <code>EXPIREAT</code> 可以让缓存的有效期与业务结束时间关联，但还需要考虑时间精度、过期时间已在过去等情况。</p><h3 id="_4-lua-脚本适用于需要原子执行的多步操作" tabindex="-1">4. Lua 脚本适用于需要原子执行的多步操作 <a class="header-anchor" href="#_4-lua-脚本适用于需要原子执行的多步操作" aria-label="Permalink to &quot;4. Lua 脚本适用于需要原子执行的多步操作&quot;">​</a></h3><p>如果两个操作之间不能被其他客户端命令打断，可以考虑 Lua**。但不应该为了简单的单条 Redis 命令而无必要地引入脚本。**</p><h3 id="_5-key-是否存在不代表业务数据一定有效" tabindex="-1">5. Key 是否存在不代表业务数据一定有效 <a class="header-anchor" href="#_5-key-是否存在不代表业务数据一定有效" aria-label="Permalink to &quot;5. Key 是否存在不代表业务数据一定有效&quot;">​</a></h3><p>空值缓存中的 Key 存在，表示系统在某个时间点记录了查询不到有效模板的结果。它并不能永久证明该模板不存在，因此需要结合过期策略和数据更新逻辑考虑缓存一致性。</p><h2 id="九、总结" tabindex="-1">九、总结 <a class="header-anchor" href="#九、总结" aria-label="Permalink to &quot;九、总结&quot;">​</a></h2><p>Spring Data Redis 为 Java 开发者提供了更方便的 Redis 操作接口。<code>opsForValue()</code>、<code>opsForHash()</code> 等方法分别对应不同的数据结构，而 <code>hasKey()</code>、<code>expire()</code>、<code>delete()</code> 等方法则用于处理 Key 的存在性、有效期和删除操作。</p><p>学习这些 API 时，不能只记住方法名称，还需要知道它们对应什么 Redis 命令，以及为什么在业务中使用。</p><p>通过 oneCoupon 的优惠券模板查询流程，可以看到正常缓存、空值缓存、Hash 写入、过期时间管理和 Lua 原子操作是如何配合的。理解这些基础操作之后，再学习缓存穿透、缓存击穿、分布式锁和高并发库存，就会有更扎实的基础。</p><h3 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h3><ul><li><a href="https://docs.spring.io/spring-data/redis/reference/" target="_blank" rel="noreferrer">Spring Data Redis 官方参考文档</a></li><li><a href="https://redis.io/docs/latest/commands/" target="_blank" rel="noreferrer">Redis 官方命令文档</a></li><li><a href="https://redis.io/docs/latest/develop/programmability/eval-intro/" target="_blank" rel="noreferrer">Redis 官方 Lua 脚本文档</a></li></ul><h2 id="个人感悟" tabindex="-1">个人感悟： <a class="header-anchor" href="#个人感悟" aria-label="Permalink to &quot;个人感悟：&quot;">​</a></h2><p><strong>1、序列化方式</strong></p><p>stringTemplate是一种序列化的方式，这意味着redis中经他手存进去的数据，都是字符串类型，也就是“”； （ 所以你在 redis-cli 里看到的是明文。 ）</p><p>而redis中的数据统一为字符串应该也没什么影响，遇到数字，日期这些特殊的存储，需要反序列化时再用函数去将其转化相应的 形式就可以了。</p><p><strong>2、key的形式</strong></p><p>Redis 本身没有“表”“文件夹”“数据库 schema”这种概念，所有 key 都是平铺的。 所以 coupon:template:1001 里的冒号，其实是在人为划分层级：</p><p>很多 Redis 客户端看到冒号，会自动折叠成树状结构</p><p>推荐写法一般是：项目/业务 : 模块/实体 : ID；比如：mall:coupon:template:1001</p><p>1）分层之后，排查问题会方便很多。</p><p>2）很多 Redis 客户端看到冒号，会自动折叠成树状结构</p><p>3）冒号分层是好事，但也不是越多越好。一般建议控制在 3～5 层左右，</p><p>Redis 并不因为冒号多就“真的建立目录”，它底层还是把 key 当成一个完整字符串处理。冒号分层只是约定，不是 Redis 的强制机制。</p><p>另外 Hash 有一个容易踩坑的点：<strong>过期时间只能设在 key 上，不能单独给某个 field 设置过期。</strong></p><p><strong>3、添加数据</strong></p><p>SET username zhangsan 表示添加一个key-value</p><p>hset x x x 表示添加一个hash结构 ；</p><p>即：</p><ul><li><strong>String</strong>：一个 key 对应一个值；</li><li><strong>Hash</strong>：一个 key 对应多个 field-value；</li><li><strong>List</strong>：一个 key 对应一个有序列表，可重复；</li><li><strong>Set</strong>：一个 key 对应一个无序集合，不可重复；</li><li><strong>ZSet</strong>：一个 key 对应一个有序集合，每个成员带一个 score；</li><li><strong>Geo / Stream / Bitmap / HyperLogLog</strong>：都是特殊场景用的结构。</li></ul>`,173)])])}const g=s(t,[["render",i]]);export{u as __pageData,g as default};
